import { productVisibleForPostal, storeVisibleForPostal } from './delivery-context.js';
import { readMarketplace, pickupAllowed } from './marketplace-settings.js';
import { renderConfiguredModules, bindConfiguredCarousels } from './configured-modules.js';
import { createProductExperience } from './product-experience.js';
// Fluxos do Prompt 2: catálogo e logística são demonstrativos, sem consulta externa.
export function createDiscovery({products,stores,categories,state,card,badge,icon,money,escape,render,modal,toast}) {
  const typeExperience=createProductExperience({products,state,money,escape,icon,modal,toast});
  const cartLines=new Map();
  let variation='',quantity=1,lastProduct=null,gallery=0;
  const details=products.map((p,i)=>({brand:p.category==='Eletrônicos'?'Conecta':p.category==='Casa & decoração'?'Aurora Casa':p.category==='Jardim & plantas'?'Verde & Vida':p.category==='Beleza & cuidados'?'Essencial Care':'Essencial',stock:i===5?0:8,attribute:[1,8].includes(i)?'Vários tamanhos':p.description.split(' · ').at(-1),material:p.category.includes('Moda')?'Consulte a composição da variação':p.description.split(' · ')[0]}));
  const route=()=>{const [path,query='']=location.hash.slice(1).split('?');return {path,params:new URLSearchParams(query)}};
  const navigate=hash=>{if(location.hash===hash){render();window.scrollTo(0,0)}else location.hash=hash};
  const search=(data={})=>{const params=new URLSearchParams();Object.entries(data).forEach(([k,v])=>{if(v!==''&&v!==null&&v!==undefined)params.set(k,v)});navigate('#/busca'+(params.size?'?'+params:''))};
  const normalize=s=>s.normalize('NFD').replace(/\p{Diacritic}/gu,'').toLowerCase();
  const choiceStock=(id,v)=>[1,8].includes(id)?v==='37'?0:v==='36'?4:8:details[id].stock;
  const crumb=items=>`<nav class="detail-crumb" aria-label="Caminho da página"><a href="#">Início</a>${items.map(([label,url])=>`<span>›</span>${url?`<a href="${url}">${escape(label)}</a>`:`<span aria-current="page">${escape(label)}</span>`}`).join('')}</nav>`;
  const blank=(title,text)=>`<div class="empty">${icon('search')}<h2>${title}</h2><p>${text}</p><a class="btn" href="#/busca">Explorar produtos</a></div>`;
  function miniCard(p){return card(p).replace('<div class="product-meta">',`<div class="listing-brand">${escape(details[p.id].brand)}${details[p.id].stock===0?' · Sem estoque':''}</div><div class="product-meta">`)}
  function filterForm(params){const selected=k=>params.get(k)||'';const select=(name,label,options)=>`<label>${label}<select name="${name}"><option value="">Todos</option>${options.map(([value,text])=>`<option value="${escape(value)}" ${selected(name)===String(value)?'selected':''}>${escape(text)}</option>`).join('')}</select></label>`;return `<form class="catalog-filters"><input type="hidden" name="q" value="${escape(selected('q'))}"><input type="hidden" name="sort" value="${escape(selected('sort'))}">${select('category','Categoria',categories.map(([c])=>[c,c]))}${select('brand','Marca',[...new Set(details.map(d=>d.brand))].map(b=>[b,b]))}${select('city','Cidade da loja',[['Cianorte','Cianorte'],['Maringá','Maringá']])}${select('store','Loja',stores.map((s,i)=>[i,s.name]).filter(([i])=>storeVisibleForPostal(i)))}<fieldset><legend>Preço dos produtos</legend><div class="price-range"><label>Mínimo (R$)<input type="number" name="min" min="0" step="0.01" value="${escape(selected('min'))}" placeholder="0"></label><label>Máximo (R$)<input type="number" name="max" min="0" step="0.01" value="${escape(selected('max'))}" placeholder="Sem limite"></label></div></fieldset>${select('attribute','Característica',[...new Set(details.map(d=>d.attribute))].map(a=>[a,a]))}<p class="filter-error" role="alert"></p><button class="btn" type="submit">Aplicar filtros</button><button class="text-link" type="button" data-discovery="reset-filters">Limpar filtros</button><p class="catalog-help">A cidade da loja não garante entrega. Consulte a cobertura pelo endereço.</p></form>`}
  function listing(params){const query=params.get('q')||'';let list=products.filter(p=>{const d=details[p.id],s=stores[p.store];return productVisibleForPostal(p)&&(!query||normalize(p.name+' '+s.name+' '+p.category+' '+d.brand).includes(normalize(query)))&&(!params.get('category')||p.category===params.get('category'))&&(!params.get('brand')||d.brand===params.get('brand'))&&(!params.get('city')||s.city===params.get('city'))&&(!params.has('store')||String(p.store)===params.get('store'))&&(!params.get('attribute')||d.attribute===params.get('attribute'))&&(!params.get('min')||p.price>=Number(params.get('min')))&&(!params.get('max')||p.price<=Number(params.get('max')))&&(!params.get('favorites')||state.favorites.has(p.id))});
    const order=params.get('sort')||'relevance';list.sort(order==='lowest'?(a,b)=>a.price-b.price:order==='highest'?(a,b)=>b.price-a.price:order==='name'?(a,b)=>a.name.localeCompare(b.name,'pt-BR'):(a,b)=>a.id-b.id);
    const status=params.get('status');const labels={q:'Busca',category:'Categoria',brand:'Marca',city:'Cidade',store:'Loja',attribute:'Característica',min:'A partir de',max:'Até',favorites:'Favoritos'};
    const chips=[...params].filter(([k])=>labels[k]).map(([k,v])=>`<button data-discovery="remove-filter" data-key="${k}" class="filter-chip">${labels[k]}: ${escape(k==='store'?stores[Number(v)]?.name||v:v)} <span aria-label="Remover">×</span></button>`).join('');
    return `${crumb([[params.get('category')||'Busca e categorias']])}<div class="discovery-heading"><div><span class="eyebrow">ENCONTRE NO COMÉRCIO LOCAL</span><h1>${params.get('favorites')?'Seus favoritos':query?`Resultados para “${escape(query)}”`:escape(params.get('category')||'Explore os produtos')}</h1><p>${list.length} produtos encontrados · Sua região: ${state.city}</p></div><button class="text-link" data-action="location">${icon('pin')} Alterar região</button></div><div class="catalog-layout"><aside class="filter-sidebar"><h2>Filtrar produtos</h2>${filterForm(params)}</aside><section aria-label="Resultados da busca"><div class="catalog-toolbar"><button class="btn secondary mobile-filter" data-discovery="filters">${icon('menu')} Filtrar</button><span>${list.length} resultados</span><label>Ordenar por <select id="catalog-sort">${[['relevance','Relevância'],['lowest','Menor preço'],['highest','Maior preço'],['name','Nome do produto']].map(([k,l])=>`<option value="${k}" ${k===order?'selected':''}>${l}</option>`).join('')}</select></label></div><div class="filter-chips">${chips}</div><div class="listing-grid" aria-live="polite">${status==='error'?`<div class="empty"><h2>Não foi possível carregar os produtos</h2><p>A busca falhou nesta simulação. Tente novamente.</p><button class="btn" data-discovery="retry">Tentar novamente</button></div>`:status==='loading'?'<p role="status">Buscando produtos…</p>'+Array.from({length:6},()=>'<div class="skeleton" aria-hidden="true"></div>').join(''):list.length?list.map(miniCard).join(''):blank('Não encontramos produtos','Experimente remover filtros ou buscar por outro termo.')}</div><div class="catalog-demo"><span>Estados do protótipo:</span><button data-discovery="list-state" data-status="loading">Carregamento</button><button data-discovery="list-state" data-status="error">Falha de busca</button></div></section></div>`;
  }
  function productPage(id){const p=products[id];if(p&&!productVisibleForPostal(p))return blank('Produto fora da sua região','Confirme sua cidade e CEP pelo cabeçalho para consultar disponibilidade.');if(!p)return blank('Produto não encontrado','Este produto não faz parte do catálogo demonstrativo.');if(lastProduct!==id){variation=[1,8].includes(id)?'':'Único';quantity=1;gallery=0;lastProduct=id}const s=stores[p.store],d=details[id];return `${crumb([[p.category,'#/busca?category='+encodeURIComponent(p.category)],[p.name]])}<div class="product-detail"><section class="gallery" aria-label="Imagens do produto"><button class="gallery-main" data-discovery="zoom" aria-label="Ampliar imagem do produto"><img src="${p.image}" alt="${p.name}" class="${gallery?'detail-crop':''}"><span>${icon('search')} Ampliar imagem</span></button><div class="gallery-thumbs">${[0,1].map(i=>`<button data-discovery="gallery" data-index="${i}" aria-label="${i?'Detalhe da mesma fotografia':'Fotografia principal'}" aria-pressed="${gallery===i}"><img class="${i?'detail-crop':''}" src="${p.image}" alt=""><span>${i?'Detalhe':'Principal'}</span></button>`).join('')}</div><p class="catalog-help">Fotografias ilustrativas. A segunda visualização amplia a mesma imagem.</p></section><section class="product-buy"><div class="product-brand">${d.brand} <span>· REF. ML-${String(id+1).padStart(4,'0')}</span></div><h1>${p.name}</h1><p class="detail-summary">${p.description}</p><div class="sold-by">Vendido por <a href="#/loja/${p.store}">${escape(s.name)}</a> ${badge(s)}<span>${escape(s.city)}, PR</span></div><div class="detail-price">${money(p.price)}</div><p class="catalog-help">Preço demonstrativo do produto. Frete calculado separadamente.</p><fieldset class="variations"><legend>${[1,8].includes(id)?'Selecione o tamanho':'Variação'}</legend>${([1,8].includes(id)?['36','37','38','39','40']:['Único']).map(v=>`<button data-discovery="variation" data-value="${v}" aria-pressed="${variation===v}">${v}</button>`).join('')}</fieldset><p id="stock-status" class="stock-status">${!variation?'Selecione uma variação para consultar o estoque.':choiceStock(id,variation)?'Disponível para compra.':'Produto sem estoque nesta variação'}</p><div class="purchase-row"><label>Quantidade<input id="product-quantity" type="number" min="1" step="1" value="${quantity}" aria-describedby="purchase-error"></label><button class="btn" data-discovery="buy" ${variation&&choiceStock(id,variation)===0?'disabled':''}>${icon('bag')} Adicionar à sacola</button></div><p id="purchase-error" class="filter-error" role="alert"></p><div class="shipping-box"><h2>${icon('truck')} Entrega ou retirada</h2><form id="shipping-form"><label>CEP do comprador<input name="cep" pattern="[0-9]{8}" required placeholder="8 dígitos"></label><label>Endereço para consulta<input name="address" required minlength="5" placeholder="Rua e número — use um endereço fictício" autocomplete="off"></label><div class="shipping-fields"><label>Cidade<select name="city"><option ${state.city==='Cianorte'?'selected':''}>Cianorte</option><option ${state.city==='Maringá'?'selected':''}>Maringá</option></select></label><button class="btn secondary" type="submit">Consultar</button></div><details class="simulation-options"><summary>Cenário demonstrativo</summary><label>Simular resposta<select name="scenario"><option value="ok">Trajeto de 3,4 km · dentro da cobertura</option><option value="outside">Endereço fora da cobertura</option><option value="error">Falha na consulta do trajeto</option></select></label></details><p class="catalog-help">Simulação local, sem geocodificação ou consulta de ruas. A região selecionada não garante cobertura.</p></form><div id="shipping-result" aria-live="polite"></div><div class="pickup-note" hidden>${icon('store')}<div><b>Retirada na loja</b><p>Rua Exemplo, ${100+p.store*100} · ${escape(s.city)} (endereço fictício).<br>Aguarde a confirmação de que o pedido está pronto.</p></div></div></div></section></div><section class="product-information"><h2>Conheça o produto</h2><p>${p.name}: uma opção da ${escape(s.name)} para o seu dia a dia. Esta descrição compõe o catálogo demonstrativo, sem representar uma oferta real.</p><h3>Atributos e especificações</h3><dl><div><dt>Marca demonstrativa</dt><dd>${d.brand}</dd></div><div><dt>Categoria</dt><dd>${p.category}</dd></div><div><dt>Apresentação</dt><dd>${p.description}</dd></div><div><dt>Variações</dt><dd>${[1,8].includes(id)?'Tamanhos 36 a 40':'Única'}</dd></div><div><dt>Origem da oferta</dt><dd>${escape(s.name)} · ${escape(s.city)}</dd></div></dl></section><section class="section"><div class="section-head"><h2>Mais desta loja</h2><a class="text-link" href="#/loja/${p.store}">Conhecer ${escape(s.name)} →</a></div><div class="listing-grid related-grid">${products.filter(x=>x.store===p.store&&x.id!==id).slice(0,4).map(miniCard).join('')}</div></section>`}
  function storePage(id,params){const s=stores[id];if(s&&!storeVisibleForPostal(id))return blank('Loja fora da sua região','Esta loja não oferece entrega ou retirada para o CEP selecionado. Altere a localização no cabeçalho.');if(!s)return blank('Loja não encontrada','Explore as lojas da região pela página inicial.');const own=products.filter(p=>p.store===id),q=params.get('q')||'',cat=params.get('category')||'';const list=own.filter(p=>(!q||normalize(p.name).includes(normalize(q)))&&(!cat||p.category===cat));return `${crumb([['Lojas da região','#lojas'],[s.name]])}<section class="store-profile"><div class="store-logo">${s.initial}</div><div><h1>${escape(s.name)}</h1><p>${s.desc} · ${escape(s.city)}, PR</p>${badge(s)}</div><a class="btn secondary" href="#informacoes-loja">Entrega e retirada</a></section>${renderConfiguredModules(['official','indicated'].includes(readMarketplace().stores.find(x=>x.id===id)?.seal)?readMarketplace().storeModules[id]||[]:[],own,card,escape)}${s.type?`<section class="store-editorial ${id===1?'fashion-editorial':''}"><div><span class="eyebrow">${id===0?'BEM-VINDO À CASA AURORA':'ESSENCIAL CONCEPT'}</span><h2>${id===0?'Um novo olhar<br>para o seu lar.':'Escolhas que combinam<br>com quem você é.'}</h2><p>${id===0?'Texturas, luz e detalhes para criar seu lugar favorito.':'Estilo, tecnologia e cuidados para acompanhar sua rotina.'}</p><a class="btn" href="#catalogo-loja">Explorar a coleção →</a></div><img src="${own[0].image}" alt="Seleção ilustrativa da ${escape(s.name)}"></section>`:`<div class="plain-store-intro"><h2>Mais natureza na sua rotina.</h2><p>Conheça o catálogo da Verde & Vida e consulte entrega ou retirada.</p></div>`}<section class="section" id="catalogo-loja"><div class="section-head"><div><h2>Explore a nossa loja</h2><p>${list.length} produtos · Somente ofertas de ${escape(s.name)}</p></div><form class="store-search" data-store="${id}"><input name="q" aria-label="Buscar nesta loja" placeholder="Buscar nesta loja" value="${escape(q)}"><button class="btn" aria-label="Pesquisar na loja">${icon('search')}</button></form></div><div class="store-categories"><a href="#/loja/${id}" ${!cat?'aria-current="true"':''}>Todos</a>${[...new Set(own.map(p=>p.category))].map(c=>`<a href="#/loja/${id}?category=${encodeURIComponent(c)}" ${cat===c?'aria-current="true"':''}>${c}</a>`).join('')}</div><div class="listing-grid related-grid">${list.length?list.map(miniCard).join(''):blank('Nenhum produto nesta seleção','Experimente outra categoria ou outra busca na loja.')}</div></section>${s.type?`<section class="store-banner-pair"><a href="#/produto/${own.at(-1).id}"><span>UM DETALHE FAZ A DIFERENÇA<strong>${own.at(-1).name}</strong><small>Conhecer produto →</small></span><img src="${own.at(-1).image}" alt=""></a><a href="#/produto/${own[0].id}"><span>ESCOLHAS DA LOJA<strong>${own[0].name}</strong><small>Ver detalhes →</small></span><img src="${own[0].image}" alt=""></a></section><section class="section"><div class="section-head"><h2>Seleção da ${escape(s.name)}</h2></div><div class="listing-grid related-grid">${own.slice().reverse().slice(0,4).map(miniCard).join('')}</div></section>`:''}<section class="store-business" id="informacoes-loja"><div><h2>Sobre a ${escape(s.name)}</h2><p>Empresa fictícia utilizada para demonstrar o marketplace.<br>Razão social: ${escape(s.name)} Comércio Demonstrativo.<br>CNPJ: não informado — exemplo visual.</p></div><div><h3>Entrega e retirada</h3><p>Entrega pela própria loja, sujeita à consulta do endereço. Frete proporcional à distância pelas ruas.<br>Retirada: Rua Exemplo, ${100+id*100}, ${escape(s.city)} (fictício). Aguarde o pedido ficar pronto.</p></div><div><h3>Informações da loja</h3><p>${s.type?'Selo demonstrativo: Loja '+s.type+'. O selo não é garantia de entrega ou menor preço.':'Loja comum com apresentação padrão.'} Documentos de validação são privados.</p></div></section>`}
  function renderRoute(){const {path,params}=route();let html;if(path==='/busca')html=listing(params);else if(path?.startsWith('/produto/'))html=productPage(Number(path.split('/')[2]));else if(path?.startsWith('/loja/'))html=storePage(Number(path.split('/')[2]),params);else return;document.querySelectorAll('.carousel-track').forEach(t=>t._cleanup?.());document.querySelector('#conteudo').innerHTML=html;bindConfiguredCarousels();document.querySelector('#conteudo').classList.add('discovery-page');if(path?.startsWith('/loja/')){const id=Number(path.split('/')[2]);if(['official','indicated'].includes(readMarketplace().stores.find(x=>x.id===id)?.seal)&&readMarketplace().storeModules[id]?.length)document.querySelectorAll('.store-editorial,.store-banner-pair').forEach(el=>el.remove());}if(path?.startsWith('/produto/')&&document.querySelector('.product-buy'))typeExperience.mount(Number(path.split('/')[2]));const input=document.querySelector('.search input');input.value=path==='/busca'?params.get('q')||'':'';document.title=(path==='/busca'?'Busca e categorias':path.startsWith('/produto/')?products[Number(path.split('/')[2])]?.name:stores[Number(path.split('/')[2])]?.name)+' · Marketplace Local';if(path==='/busca'&&params.get('status')==='loading'){const current=location.hash;setTimeout(()=>{if(location.hash===current){params.delete('status');navigate('#/busca?'+params)}},1000)}}
  function showCart(){modal('Sua sacola',cartLines.size?`${[...cartLines].map(([key,line])=>`<div class="cart-item"><img src="${products[line.id].image}" alt=""><div>${products[line.id].name}<small>${stores[products[line.id].store].name} · ${line.variation} · ${money(products[line.id].price)}</small></div><button data-discovery="cart-minus" data-line="${key}" aria-label="Diminuir quantidade">−</button><b>${line.qty}</b><button data-discovery="cart-plus" data-line="${key}" aria-label="Aumentar quantidade">+</button></div>`).join('')}<div class="dialog-row"><b>Subtotal dos produtos</b><strong class="price">${money([...cartLines.values()].reduce((sum,l)=>sum+products[l.id].price*l.qty,0))}</strong></div><p class="dialog-copy">Frete não incluído. Sacola demonstrativa; o checkout será desenvolvido no Prompt 3.</p>`:blank('Sua sacola está vazia','Escolha um produto e selecione a variação para adicionar.'))}
  function syncCart(){state.cart.clear();cartLines.forEach(l=>state.cart.set(l.id,(state.cart.get(l.id)||0)+l.qty));document.querySelectorAll('.count').forEach(el=>el.textContent=[...state.cart.values()].reduce((a,b)=>a+b,0))}
  document.addEventListener('click',e=>{const el=e.target.closest('[data-discovery],[data-action],[data-subcategory],.brand,.mobile-nav a');if(!el)return;const action=el.dataset.action,d=el.dataset.discovery;const {path,params}=route();const handled=!!d||['product','store','category','add','cart','clear','favorites','favorite','remove','loading','empty'].includes(action)||el.hasAttribute('data-subcategory')||el.matches('.brand,.mobile-nav a');if(!handled)return;e.preventDefault();e.stopImmediatePropagation();const id=Number(el.dataset.id);if(el.matches('.brand')||el.matches('.mobile-nav a.active')){navigate('#');return}if(el.matches('.mobile-nav a')){search();return}if(el.hasAttribute('data-subcategory')){search({category:el.dataset.parent,q:el.dataset.subcategory});return}if(action==='product'||action==='add'){document.querySelector('#modal').close();navigate('#/produto/'+id);return}if(action==='store'){navigate('#/loja/'+id);return}if(action==='category'){search({category:el.dataset.category});return}if(action==='clear'){search();return}if(action==='favorites'){search({favorites:'1'});return}if(action==='cart'){showCart();return}if(action==='loading'||action==='empty'){search(action==='loading'?{status:'loading'}:{q:'produto inexistente'});return}if(action==='favorite'){state.favorites.has(id)?state.favorites.delete(id):state.favorites.add(id);document.querySelectorAll('.favorite').forEach(b=>b.setAttribute('aria-pressed',String(state.favorites.has(Number(b.dataset.id)))));if(params.get('favorites'))render();toast('Favoritos atualizados.');return}
    if(d==='filters'){modal('Filtrar produtos',filterForm(params));return}if(d==='reset-filters'){document.querySelector('#modal').close();search({q:params.get('q')||''});return}if(d==='remove-filter'){params.delete(el.dataset.key);navigate('#/busca?'+params);return}if(d==='list-state'){params.set('status',el.dataset.status);navigate('#/busca?'+params);return}if(d==='retry'){params.delete('status');navigate('#/busca?'+params);return}
    if(d==='gallery'){gallery=Number(el.dataset.index);document.querySelector('.gallery-main img').classList.toggle('detail-crop',gallery===1);document.querySelectorAll('[data-discovery=gallery]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.index)===gallery)));return}if(d==='zoom'){const p=products[Number(path.split('/')[2])];modal(p.name,`<img class="zoom-photo" src="${p.image}" alt="${p.name}">`);return}
    if(d==='variation'){variation=el.dataset.value;document.querySelectorAll('[data-discovery=variation]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.value===variation)));const stock=choiceStock(Number(path.split('/')[2]),variation);document.querySelector('#stock-status').textContent=stock?'Disponível para compra.':'Produto sem estoque nesta variação';document.querySelector('[data-discovery=buy]').disabled=stock===0;document.querySelector('#purchase-error').textContent='';return}
    if(d==='buy'){const id=Number(path.split('/')[2]),qty=Number(document.querySelector('#product-quantity').value),err=document.querySelector('#purchase-error');if(!variation){err.textContent='Selecione uma variação antes de adicionar à sacola.';return}const key=id+'|'+variation,existing=cartLines.get(key)?.qty||0,stock=choiceStock(id,variation);if(!Number.isInteger(qty)||qty<1){err.textContent='Informe uma quantidade inteira maior que zero.';return}if(existing+qty>stock){err.textContent='Estoque insuficiente para a quantidade solicitada.';return}cartLines.set(key,{id,variation,qty:existing+qty});quantity=qty;syncCart();err.textContent='';modal('Produto adicionado à sacola',`<div class="added-product">${icon('check')}<div><h3>${products[id].name}</h3><p>${qty} unidade(s) · ${variation} · ${stores[products[id].store].name}</p></div></div><div class="dialog-row"><button class="btn secondary" data-action="close">Continuar comprando</button><button class="btn" data-discovery="open-cart">Ver sacola →</button></div>`);return}
    if(d==='open-cart'){showCart();return}if(d==='cart-minus'||d==='cart-plus'){const key=el.dataset.line,line=cartLines.get(key);if(!line)return;if(d==='cart-plus'&&line.qty>=choiceStock(line.id,line.variation)){toast('Quantidade máxima disponível atingida.');return}line.qty+=d==='cart-plus'?1:-1;if(line.qty<=0)cartLines.delete(key);syncCart();showCart();return}
  },true);
  document.addEventListener('submit',e=>{const f=e.target;if(f.matches('.search')){e.preventDefault();e.stopImmediatePropagation();search({q:new FormData(f).get('q').trim()});return}if(f.matches('.store-search')){e.preventDefault();e.stopImmediatePropagation();navigate('#/loja/'+f.dataset.store+'?q='+encodeURIComponent(new FormData(f).get('q').trim()));return}if(f.matches('.catalog-filters')){e.preventDefault();e.stopImmediatePropagation();const data=Object.fromEntries(new FormData(f));if(data.min&&data.max&&Number(data.min)>Number(data.max)){f.querySelector('.filter-error').textContent='O preço mínimo não pode superar o máximo.';return}document.querySelector('#modal').close();search(data);return}if(f.id==='shipping-form'){e.preventDefault();e.stopImmediatePropagation();const values=new FormData(f),id=Number(route().path.split('/')[2]),s=stores[products[id].store],result=document.querySelector('#shipping-result');const pickup=pickupAllowed(readMarketplace().stores.find(x=>x.id===products[id].store),values.get('cep'));document.querySelector('.pickup-note').hidden=!pickup;if(values.get('scenario')==='error'){result.innerHTML='<div class="shipping-error"><b>Não foi possível consultar o trajeto.</b><p>Selecione outro cenário demonstrativo e tente novamente. Nenhum frete foi calculado.</p></div>';return}if(values.get('scenario')==='outside'||values.get('city')!==s.city){result.innerHTML='<div class="shipping-error"><b>Endereço fora da cobertura nesta simulação.</b><p>Altere o endereço/cenário ou considere a retirada na loja.</p></div>';return}const rate=readMarketplace().stores.find(s=>s.id===products[id].store).rate/100;result.innerHTML=`<div class="shipping-quote"><span class="eyebrow">COTAÇÃO ILUSTRATIVA</span><div><b>Entrega pela ${escape(s.name)}</b><strong>${money(Math.round(3.4*rate*100)/100)}</strong></div><p>Trajeto fictício: 3,4 km × ${money(rate)}/km.</p><dl><dt>Previsão de despacho</dt><dd>Acompanhe a previsão após a confirmação do pagamento.</dd><dt>Previsão de chegada</dt><dd>Após a saída para entrega: cerca de ${Math.ceil(3.4*readMarketplace().minutesPerKm)} minutos neste trajeto simulado.</dd></dl></div>`}} ,true);
  document.addEventListener('change',e=>{if(e.target.id==='catalog-sort'){const {params}=route();params.set('sort',e.target.value);navigate('#/busca?'+params)}});
  document.addEventListener('click',e=>{const a=e.target.closest('a');if(a&&['#catalogo-loja','#informacoes-loja'].includes(a.getAttribute('href'))){e.preventDefault();document.querySelector(a.getAttribute('href'))?.scrollIntoView()}},true);
  window.addEventListener('hashchange',()=>{document.querySelector('#modal').close();render();if(['#lojas','#categorias','#produtos'].includes(location.hash))document.querySelector(location.hash)?.scrollIntoView();else window.scrollTo(0,0)});
  return {render:renderRoute};
}
